판 = [input("첫째 줄: "), input("둘째 줄: "), input("셋째 줄: ")]
이긴쪽 = ""
for 돌 in "OX":
    for i in range(3):
        if 판[i][0] == 돌 and 판[i][1] == 돌 and 판[i][2] == 돌:
            이긴쪽 = 돌
        if 판[0][i] == 돌 and 판[1][i] == 돌 and 판[2][i] == 돌:
            이긴쪽 = 돌
    if 판[0][0] == 돌 and 판[1][1] == 돌 and 판[2][2] == 돌:
        이긴쪽 = 돌
    if 판[0][2] == 돌 and 판[1][1] == 돌 and 판[2][0] == 돌:
        이긴쪽 = 돌
if 이긴쪽 == "":
    print("비김")
else:
    print(이긴쪽, "이김")
